PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel 
       (COALESCE(?txCount, 0) AS ?transactionCount) 
       (COALESCE(?holdCount, 0) AS ?holdingCount) 
       (COALESCE(?goalCount, 0) AS ?goalCount) 
       (COALESCE(?scenarioCount, 0) AS ?scenarioCount)
WHERE {
  # categories linked to at least one investor
  ?inv a wm:Investor .
  ?inv wm:hasCategory ?cat .
  OPTIONAL { ?cat rdfs:label ?catLabel . }

  # transaction (CashFlow) count per category
  OPTIONAL {
    SELECT ?cat (COUNT(DISTINCT ?cf) AS ?txCount)
    WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv2 .
      ?inv2 wm:hasCategory ?cat .
    } GROUP BY ?cat
  }

  # holding (PortfolioHolding) count per category
  OPTIONAL {
    SELECT ?cat (COUNT(DISTINCT ?ph) AS ?holdCount)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:heldByInvestor ?inv2 .
      ?inv2 wm:hasCategory ?cat .
    } GROUP BY ?cat
  }

  # goal (InvestmentGoal) count per category
  OPTIONAL {
    SELECT ?cat (COUNT(DISTINCT ?goal) AS ?goalCount)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv2 .
      ?inv2 wm:hasCategory ?cat .
    } GROUP BY ?cat
  }

  # scenario (ScenarioRebalancing) count per category
  OPTIONAL {
    SELECT ?cat (COUNT(DISTINCT ?sc) AS ?scenarioCount)
    WHERE {
      ?sc a wm:ScenarioRebalancing .
      ?sc wm:scenarioRebalancingOfInvestor ?inv2 .
      ?inv2 wm:hasCategory ?cat .
    } GROUP BY ?cat
  }
}
GROUP BY ?cat ?catLabel ?txCount ?holdCount ?goalCount ?scenarioCount

